curl https://www.troquecommerce.com.br/api/mcp \
  --header 'Authorization: Bearer SEU-TOKEN' \
  --header 'Content-Type: application/json' \
  --header 'Accept: application/json, text/event-stream' \
  --data '{
  "jsonrpc": "2.0",
  "id": 1,
  "method": "tools/call",
  "params": {
    "name": "prepare_reverse_order",
    "arguments": {
      "ecommerce_number": "10234",
      "customer_identifier": "maria.souza@exemplo.com"
